#include "gtest/internal/custom/gtest.h"

using ::testing::AddGlobalTestEnvironment;
using ::testing::InitGoogleTest;
using ::testing::UnitTest;

// Used by tests to register their events.
std::vector<std::string>* g_events = nullptr;

namespace testing {
namespace internal {

class EventRecordingListener : public TestEventListener {
 public:
  explicit EventRecordingListener(const char* name) : name_(name) {}

 protected:
  // Existing event handling methods...

 private:
  std::string GetFullMethodName(const char* name) { return name_ + "." + name; }

  std::string name_;
};

// New listener to add additional logging support
class ExtendedEventRecordingListener : public EventRecordingListener {
 public:
  explicit ExtendedEventRecordingListener(const char* name)
      : EventRecordingListener(name) {}

 protected:
  void OnTestPartResult(const TestPartResult& test_part_result) override {
    EventRecordingListener::OnTestPartResult(test_part_result);
    // Additional logging can be added here
    if (test_part_result.type() == TestPartResult::kFatalFailure) {
      g_events->push_back(GetFullMethodName("FatalTestPartFailure"));
    }
  }

  void OnEnvironmentsSetUpEnd(const UnitTest& /*unit_test*/) override {
    g_events->push_back(GetFullMethodName("OnEnvironmentsSetUpEnd - Extended"));
    EventRecordingListener::OnEnvironmentsSetUpEnd(/*unit_test*/);
  }

  // Additional methods can be overridden similarly...
};

// Other existing classes...

class ListenerTest : public Test {
 protected:
  // ...
};

TEST_F(ListenerTest, DoesFoo) {
  // ...
}

TEST_F(ListenerTest, DoesBar) {
  // ...
}

}  // namespace internal

}  // namespace testing

using ::testing::internal::EventRecordingListener;
using ::testing::internal::ExtendedEventRecordingListener;

int main(int argc, char** argv) {
  std::vector<std::string> events;
  g_events = &events;
  InitGoogleTest(&argc, argv);

  UnitTest::GetInstance()->listeners().Append(
      new ExtendedEventRecordingListener("Extended Listener")); // Using new listener

  AddGlobalTestEnvironment(new EnvironmentInvocationCatcher);

  // Verify no events have been generated
  GTEST_CHECK_(events.empty())
      << "AddGlobalTestEnvironment should not generate any events itself.";

  // Run all tests
  int ret_val = RUN_ALL_TESTS();

  // Verify results...

  return ret_val;
}
